/**
 * Wire-compatible Secret Service cryptography (libsodium crypto_kx +
 * XChaCha20-Poly1305), verified against ../go/matii/testdata/vectors.json,
 * which is generated by the console backend.
 */
import sodium from 'libsodium-wrappers'

export class DecryptError extends Error {
  constructor() {
    super('matii: decryption failed')
  }
}

export type KeyPair = { publicKey: Uint8Array; privateKey: Uint8Array }

export const ready = () => sodium.ready

const fromHex = (hex: string) => {
  try {
    return sodium.from_hex(hex)
  } catch {
    throw new DecryptError()
  }
}

/** libsodium crypto_kx_seed_keypair. */
export const kxSeedKeyPair = (seed: Uint8Array): KeyPair => {
  const kp = sodium.crypto_kx_seed_keypair(seed)
  return { publicKey: kp.publicKey, privateKey: kp.privateKey }
}

const openRaw = (ct: Uint8Array, key: Uint8Array): Uint8Array => {
  const nonceSize = sodium.crypto_aead_xchacha20poly1305_ietf_NPUBBYTES
  if (ct.length < nonceSize + sodium.crypto_aead_xchacha20poly1305_ietf_ABYTES) throw new DecryptError()
  try {
    return sodium.crypto_aead_xchacha20poly1305_ietf_decrypt(
      null,
      ct.subarray(0, ct.length - nonceSize),
      null,
      ct.subarray(ct.length - nonceSize),
      key
    )
  } catch {
    throw new DecryptError()
  }
}

/** Open a "ph:v1:<ephemeral pk>:<base64(ciphertext||nonce)>" value addressed to `keys`. */
export const decryptAsymmetric = (ciphertext: string, keys: KeyPair): string => {
  const parts = ciphertext.split(':')
  if (parts.length !== 4 || parts[0] !== 'ph' || parts[1] !== 'v1') throw new DecryptError()
  const ephemeral = fromHex(parts[2])
  let raw: Uint8Array
  try {
    raw = sodium.from_base64(parts[3], sodium.base64_variants.ORIGINAL)
  } catch {
    throw new DecryptError()
  }
  let rx: Uint8Array
  try {
    rx = sodium.crypto_kx_server_session_keys(keys.publicKey, keys.privateKey, ephemeral).sharedRx
  } catch {
    throw new DecryptError()
  }
  return sodium.to_string(openRaw(raw, rx))
}

/** Seal plaintext to a recipient's public key. */
export const encryptAsymmetric = (plaintext: string, recipientPublic: Uint8Array): string => {
  const eph = sodium.crypto_kx_keypair()
  const tx = sodium.crypto_kx_client_session_keys(eph.publicKey, eph.privateKey, recipientPublic).sharedTx
  const nonce = sodium.randombytes_buf(sodium.crypto_aead_xchacha20poly1305_ietf_NPUBBYTES)
  const sealed = sodium.crypto_aead_xchacha20poly1305_ietf_encrypt(sodium.from_string(plaintext), null, null, nonce, tx)
  const joined = new Uint8Array(sealed.length + nonce.length)
  joined.set(sealed)
  joined.set(nonce, sealed.length)
  return `ph:v1:${sodium.to_hex(eph.publicKey)}:${sodium.to_base64(joined, sodium.base64_variants.ORIGINAL)}`
}

/** Keyed BLAKE2b-256 of a key name with the environment salt (UTF-8), as hex. */
export const keyDigest = (key: string, salt: string): string =>
  sodium.to_hex(sodium.crypto_generichash(32, sodium.from_string(key), sodium.from_string(salt)))

/** Rebuild a token's private key from share A (token) and wrapped share B (server). */
export const recoverTokenKey = (token: ParsedToken, wrappedShareHex: string): KeyPair => {
  const shareBHex = sodium.to_string(openRaw(fromHex(wrappedShareHex), fromHex(token.wrapKey)))
  const shareA = fromHex(token.shareA)
  const shareB = fromHex(shareBHex)
  if (shareA.length !== 32 || shareB.length !== 32) throw new DecryptError()
  const privateKey = shareA.map((byte, i) => byte ^ shareB[i])
  const publicKey = sodium.crypto_scalarmult_base(privateKey)
  if (sodium.to_hex(publicKey) !== token.kxPublic.toLowerCase()) {
    throw new Error("matii: token key shares do not match the token's public key")
  }
  return { publicKey, privateKey }
}

export type ParsedToken = {
  kind: 'ServiceAccount' | 'User'
  value: string
  kxPublic: string
  shareA: string
  wrapKey: string
}

/** Parse pss_service:v2 and pss_user:v1/v2 tokens (personal access tokens are issued as v1, same layout). */
export const parseToken = (raw: string): ParsedToken => {
  const parts = raw.trim().split(':')
  if (parts.length !== 6 || !(parts[1] === 'v2' || (parts[0] === 'pss_user' && parts[1] === 'v1')))
    throw new Error('matii: unsupported token format')
  const kind = parts[0] === 'pss_service' ? 'ServiceAccount' : parts[0] === 'pss_user' ? 'User' : null
  if (!kind) throw new Error('matii: unknown token type')
  if (parts.slice(2).some((p) => !/^[0-9a-f]{64}$/i.test(p))) throw new Error('matii: malformed token')
  return { kind, value: parts[2], kxPublic: parts[3], shareA: parts[4], wrapKey: parts[5] }
}
